  font-family: var(--font-mono-reference);
  font-size: var(--text-mono-reference-size);
  font-weight: var(--text-mono-reference-weight);
  letter-spacing: var(--text-mono-reference-letter-spacing);
}

.buchung-detail-page__seats {
  list-style: none;
